/**
Program flow...
	0. dataShader を使って frame buffer (fb1) に位置・速度の初期値を書き込み (offscreen rendering)
	1. fb1 の texture から前フレームの位置・速度を読み込み ==> moveShader を使って frame buffer (fb2) に計算後の位置・速度を書き込み (offscreen rendering)
	2. fb2 の texture から計算後の位置・速度を読み込み ==> pointShader で画面上に描画 (screen rendering)
	3. 現在のフレームを frame buffer (fb1) に書き込み
	4. (1)~(3) を繰り返す

Remarks:
	- particle の動きを変えたい場合は主に moveShader を編集 (フレーム間で保持したい変数がある場合は js 側で定義 ==> uniform で渡す)
	- 表示色を変えたい場合は主に pointShader を編集
**/

/**
Thanks for greatful reference,,,
	https://qiita.com/inaba_darkfox/items/47b617651a914eca30c0
		by mathfoxLab (https://openprocessing.org/user/161812?view=sketches)
	https://wgld.org/d/webgl/w083.html
		by h_doxas
**/

let _gl, gl;

const TEX_SIZE = 512; // 512x512個のパーティクルを用いる
let accell = 0; // 加速度

let fb1, fb2, flip;  // frame buffer

function setup(){
  // _gl = createCanvas(600, 600, WEBGL);
  _gl = createCanvas(windowWidth, windowWidth*.75, WEBGL);
	colorMode(HSB,360,100,100,100);
  pixelDensity(1);
  gl = _gl.GL;

  // 浮動小数点数 texture の利用可否をチェック
  const ext = gl.getExtension('OES_texture_float') || gl.getExtension('OES_texture_half_float');
  if(ext == null){ alert('float texture not supported');  return; }

  // 点描画用のインデックス
  let indices = [];
  for(let i = 0; i < TEX_SIZE * TEX_SIZE; i++){ indices.push(i); }

  // 板ポリ用 (定型)
  const positions = [
    -1.0,  1.0,  0.0,
    -1.0, -1.0,  0.0,
     1.0,  1.0,  0.0,
     1.0, -1.0,  0.0
  ];


  /* dataShader: 位置・速度の初期化用 */
  dataShader = createShader(dataVert, dataFrag);
	shader(dataShader);  // shader として登録
	// dataShader.useProgram();  // 使用する shader program を切り替え

	// attribute の初期化
	dProgram = dataShader._glProgram;
  dVbo = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, dVbo);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(positions), gl.STATIC_DRAW);
  gl.bindBuffer(gl.ARRAY_BUFFER, null);
	dLocation = gl.getAttribLocation(dProgram, 'aPosition');
	dStride = 3;


  /* moveShader: 位置・速度の計算用 */
	moveShader = createShader(moveVert, moveFrag);
	shader(moveShader);  // shader として登録
	// moveShader.useProgram();  // 使用する shader program を切り替え

	// attribute の初期化
	mProgram = moveShader._glProgram;
	mVbo = gl.createBuffer();
	gl.bindBuffer(gl.ARRAY_BUFFER, mVbo);
	gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(positions), gl.STATIC_DRAW);
	gl.bindBuffer(gl.ARRAY_BUFFER, null);
	mLocation = gl.getAttribLocation(mProgram, 'aPosition');
	mStride = 3;

	// uniform texture の初期化
	mUniformLocations = gl.getUniformLocation(mProgram, 'uTex');


  /* pointShader: 描画用 */
	pointShader = createShader(pointVert, pointFrag);
	shader(pointShader);  // shader として登録
	// pointShader.useProgram();  // 使用する shader program を切り替え

	// attribute の初期化
	pProgram = pointShader._glProgram;
	pVbo = gl.createBuffer();
	gl.bindBuffer(gl.ARRAY_BUFFER, pVbo);
	gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(indices), gl.STATIC_DRAW);
	gl.bindBuffer(gl.ARRAY_BUFFER, null);
	pLocation = gl.getAttribLocation(pProgram, 'aIndex');
	pStride = 1;

	// uniform texture の初期化
	pUniformLocations = gl.getUniformLocation(pProgram, 'uTex');


  // frame buffer object 生成 (frame buffer + depth rendering buffer + texture)
  fb1 = create_framebuffer(TEX_SIZE, TEX_SIZE, gl.FLOAT);
  fb2 = create_framebuffer(TEX_SIZE, TEX_SIZE, gl.FLOAT);
  flip = fb1;


  /** 0. dataShader で位置・速度を初期化 (offscreen rendering)
	*/
  gl.bindFramebuffer(gl.FRAMEBUFFER, fb1.f);  // frame buffer を bind
  gl.viewport(0, 0, TEX_SIZE, TEX_SIZE);  // view port を設定
  clear();

	dataShader.useProgram();  // 使用する shader program を切り替え

  // attribute をセット
	gl.bindBuffer(gl.ARRAY_BUFFER, dVbo);
	gl.enableVertexAttribArray(dLocation);
	gl.vertexAttribPointer(dLocation, dStride, gl.FLOAT, false, 0, 0);

  // uniform をセット
	dataShader.setUniform('uTexSize', TEX_SIZE);

  // draw (ただし offscreen へ rendering される)
  gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);

  // bind 解除
	gl.bindBuffer(gl.ARRAY_BUFFER, null);
  gl.viewport(0, 0, width, height); // viewport を戻す
  gl.bindFramebuffer(gl.FRAMEBUFFER, null);
}

function draw(){
	background(0);

  const _size = max(width, height);
  const mouse_x = ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / width - 0.5) * 2.0 * width / _size;
  const mouse_y = -((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / height - 0.5) * 2.0 * height / _size;
  const mouse_flag = ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed));


  /** 1. fb1 の texture から前フレームの位置・速度を読み込み ==> moveShader で位置・速度を計算 (offscreen rendering)
	*/
  gl.bindFramebuffer(gl.FRAMEBUFFER, fb2.f);  // frame buffer を bind
  gl.viewport(0, 0, TEX_SIZE, TEX_SIZE);  // viewport を設定
  clear();

	moveShader.useProgram();  // 使用する shader program を切り替え

  // attribute を設定
	gl.bindBuffer(gl.ARRAY_BUFFER, mVbo);
	gl.enableVertexAttribArray(mLocation);
	gl.vertexAttribPointer(mLocation, mStride, gl.FLOAT, false, 0, 0);

  // uniform texture を設定
	gl.activeTexture(gl.TEXTURE0 + 0);
	gl.bindTexture(gl.TEXTURE_2D, fb1.t);
	gl.uniform1i(mUniformLocations, 0);

	// uniform を設定
	moveShader.setUniform('uTexSize', TEX_SIZE);
	moveShader.setUniform("uAccell", accell);
	moveShader.setUniform("uMouseFlag", mouse_flag);
	moveShader.setUniform("uMouse", [mouse_x, mouse_y]);

  // draw (ただし offscreen に rendering する)
  gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);

  // bind 解除
	gl.bindBuffer(gl.ARRAY_BUFFER, null);
	gl.bindTexture(gl.TEXTURE_2D, null);
  gl.viewport(0, 0, width, height);  // viewport を戻す
  gl.bindFramebuffer(gl.FRAMEBUFFER, null);


  /** 2. fb2 の texture から計算後の位置・速度を読み込み ==> 画面上に描画 (screen rendering)
	(screen に rendering するので frame buffer の bind は不要)
	*/
	let col = color(frameCount%360,80,100);

	pointShader.useProgram();  // 使用する shader program を切り替え

	// attribute を設定
	gl.bindBuffer(gl.ARRAY_BUFFER, pVbo);
	gl.enableVertexAttribArray(pLocation);
	gl.vertexAttribPointer(pLocation, pStride, gl.FLOAT, false, 0, 0);

  // uniform texture を設定
	gl.activeTexture(gl.TEXTURE0 + 0);
	gl.bindTexture(gl.TEXTURE_2D, fb2.t);
	gl.uniform1i(pUniformLocations, 0);

	// uniform を設定
	pointShader.setUniform('uTexSize', TEX_SIZE);
	pointShader.setUniform('uResolution', [width, height]);
  pointShader.setUniform("uColor", [red(col)/255.0, green(col)/255.0, blue(col)/255.0]);

  // draw
  gl.drawArrays(gl.POINTS, 0, TEX_SIZE * TEX_SIZE);  // gl.LINES に変更すれば線描できる
  gl.flush();

	// bind 解除
	gl.bindBuffer(gl.ARRAY_BUFFER, null);
	gl.bindTexture(gl.TEXTURE_2D, null);


  /** 3. 現在のフレームを frame buffer (fb1) に buffering する (<== これで前フレーム情報を利用できる)
	*/
  flip = fb1;  fb1 = fb2;  fb2 = flip;

  // 加速度を更新
  if (mouse_flag) { accell = 1.0; } else { accell *= 0.95; }

	/** 4. (1)~(3) を繰り返す
	*/
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

// === Tab: dataShader ===
/* dataShader: 位置・速度の初期化用 */
const dataVert=
"precision mediump float;" +
"attribute vec3 aPosition;" + // unique attribute.
"void main(){" +
"  gl_Position = vec4(aPosition, 1.0);" +
"}";

const dataFrag=
"precision mediump float;" +
"uniform float uTexSize;" +
"void main(){" +
"  vec2 p = gl_FragCoord.xy / uTexSize;" + // 0.0~1.0 に正規化
// 初期位置と初期速度を設定
"  vec2 pos = (p - 0.5) * 2.0;" + // 位置: -1～1
"  vec2 vel = vec2(0.0, 0.0);" + // 速度: 0
"  gl_FragColor = vec4(pos, vel);" + // xy に位置， zw に速度を入れる
"}";

let dataShader;
let dProgram;
let dVbo;
let dLocation;
let dStride;

// === Tab: moveShader ===
/* moveShader: 位置・速度の計算用 */
const moveVert =
"precision mediump float;" +
"attribute vec3 aPosition;" +
"void main(){" +
"  gl_Position = vec4(aPosition, 1.0);" +
"}";

const moveFrag =
"precision mediump float;" +
"uniform sampler2D uTex;" +
"uniform float uTexSize;" +
"uniform vec2 uMouse;" +
"uniform bool uMouseFlag;" +
"uniform float uAccell;" +
"const float SPEED = 0.05;" +
"void main(){" +
"  vec2 p = gl_FragCoord.xy / uTexSize;" +
"  vec4 t = texture2D(uTex, p);" + // texture から読み出す
"  vec2 pos = t.xy;" + // 読み出した texture から位置情報を取り出す
"  vec2 velocity = t.zw;" + // 読み出した texture から速度情報を取り出す
// 更新処理 (動きを変えたい場合はここを編集)
"  vec2 v = normalize(uMouse - pos) * 0.2;" +
"  vec2 w = normalize(velocity + v);" +
"  vec4 destColor = vec4(pos + w * SPEED * uAccell, w);" + // xy に位置， zw に速度を入れる
"  if(!uMouseFlag){ destColor.zw = velocity; }" + // マウスが押されてなければ減衰
"  gl_FragColor = destColor;" +
"}";

let moveShader;
let mProgram;
let mVbo;
let mLocation;
let mStride;
let mUniformLocations;

// === Tab: pointShader ===
/* pointShader: 描画用 */
const pointVert =
"precision mediump float;" +
"attribute float aIndex;" +
"uniform sampler2D uTex;" +
"uniform vec2 uResolution;" +
"uniform float uTexSize;" +
"void main() {" +
"  float x = (mod(aIndex, uTexSize) + 0.5) / uTexSize;" +
"  float y = (floor(aIndex / uTexSize) + 0.5) / uTexSize;" +
"  vec4 t = texture2D(uTex, vec2(x, y));" +  // texture から読み出す
"  vec2 p = t.xy;" + // 読み出した texture から位置を取り出す
"  p *= vec2(min(uResolution.x, uResolution.y)) / uResolution;" +
"  gl_Position = vec4(p, 0.0, 1.0);" +
"  gl_PointSize = 1.;" +
"}";

const pointFrag =
"precision mediump float;" +
"uniform vec3 uColor;" +
"void main(){" +
"  gl_FragColor = vec4(uColor, 1.);" +  // 描画色
"}";

let pointShader;
let pProgram;
let pVbo;
let pLocation;
let pStride;
let pUniformLocations;

// === Tab: utils ===
// frame buffer object 生成 (frame buffer + depth rendering buffer + texture)
function create_framebuffer(w, h, format){
  // frame buffer の生成
  let frameBuffer = gl.createFramebuffer();
  gl.bindFramebuffer(gl.FRAMEBUFFER, frameBuffer);  // frame buffer として bind

  // depth render buffer の生成と紐付け
  let depthRenderBuffer = gl.createRenderbuffer();  // render buffer 生成
  gl.bindRenderbuffer(gl.RENDERBUFFER, depthRenderBuffer);  // render buffer として bind
  gl.renderbufferStorage(gl.RENDERBUFFER, gl.DEPTH_COMPONENT16, w, h);  // render buffer を depth buffer として設定
  gl.framebufferRenderbuffer(gl.FRAMEBUFFER, gl.DEPTH_ATTACHMENT, gl.RENDERBUFFER, depthRenderBuffer);  // frame buffer に紐付ける

  // texture の生成と紐付け
	let textureFormat = (!format) ? gl.UNSIGNED_BYTE : format;  // format check
  let fTexture = gl.createTexture();  // texture 生成
  gl.bindTexture(gl.TEXTURE_2D, fTexture);  // texture として bind
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, w, h, 0, gl.RGBA, textureFormat, null);  // カラー用のメモリ領域を確保
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);  // テクスチャパラメータ
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, fTexture, 0);  // frame buffer に紐付ける

  // bind 解除
  gl.bindTexture(gl.TEXTURE_2D, null);
  gl.bindRenderbuffer(gl.RENDERBUFFER, null);
  gl.bindFramebuffer(gl.FRAMEBUFFER, null);

  return {f : frameBuffer, d : depthRenderBuffer, t : fTexture};
}

